// ** React Imports
import { Fragment, useEffect, useState } from 'react'

// ** Reactstrap Imports
import { Button, Card, CardBody, Col, Form, Input, Badge, Label, Modal, ModalBody, ModalHeader, Row, FormFeedback } from 'reactstrap'

// ** Third Party Components
import { Controller, useForm } from 'react-hook-form'
import Swal from 'sweetalert2'
import withReactContent from 'sweetalert2-react-content'
import { updateStaff } from '../store'
import * as yup from 'yup'
import { yupResolver } from '@hookform/resolvers/yup'

// ** Custom Components
import Avatar from '@components/avatar'

// ** Utils
// import { selectThemeColors } from '@utils'

// ** Styles
import '@styles/react/libs/react-select/_react-select.scss'
import { useDispatch } from 'react-redux'
import { getUserData } from '../../../../auth/utils'

const roleColors = {
  staff: 'light-info',
  admin: 'light-danger',
  author: 'light-warning',
  maintainer: 'light-success',
  agency: 'light-primary'
}

// const statusColors = {
//   1: 'light-warning',
//   2: 'light-success',
//   inactive: 'light-secondary'
// }

// const statusText = {
//   1: 'Pending',
//   2: 'Active'
// }

// const statusOptions = [
//   { value: '1', label: 'Pending' },
//   { value: '2', label: 'Active' },
//   { value: 'suspended', label: 'Suspended' }
// ]

// const countryOptions = [
//   { value: 'uk', label: 'UK' },
//   { value: 'usa', label: 'USA' },
//   { value: 'france', label: 'France' },
//   { value: 'russia', label: 'Russia' },
//   { value: 'canada', label: 'Canada' }
// ]

// const languageOptions = [
//   { value: 'english', label: 'English' },
//   { value: 'spanish', label: 'Spanish' },
//   { value: 'french', label: 'French' },
//   { value: 'german', label: 'German' },
//   { value: 'dutch', label: 'Dutch' }
// ]

const MySwal = withReactContent(Swal)

const showErrors = (field, valueLen, min) => {
  if (valueLen === 0) {
    return `Vui lòng nhập ${field}`
  } else if (valueLen > 0 && valueLen < min) {
    return `${field} phải có ít nhất ${min} kí tự`
  } else {
    return `Vui lòng nhập ${field}`
  }
}

const UpdateSchema = yup.object().shape({
  email: yup.string().email("Vui lòng nhập email hợp lệ").min(1, (obj) => showErrors("Email", obj.value.length, obj.min)),
  name: yup.string().min(1, (obj) => showErrors("Tên", obj.value.length, obj.min)).required(),
  phone: yup.string().min(1, (obj) => showErrors("SĐT", obj.value.length, obj.min)).required().matches(/(84|0[3|5|7|8|9])+([0-9]{8})\b/g, "Số điện thoại không hợp lệ"),
  address: yup.string().min(1, (obj) => showErrors("Địa chỉ", obj.value.length, obj.min)).required()
})

const UserInfoCard = ({ selectedUser }) => {
  // ** State
  const [show, setShow] = useState(false)

  const dispatch = useDispatch()
  const userData = getUserData()
  // const store = useSelector(state => state.staffs)

  // ** Hook
  const {
    reset,
    control,
    setError,
    handleSubmit,
    formState: { errors, isDirty }
  } = useForm({
    defaultValues: {
      name: selectedUser.name,
      email: selectedUser.email,
      id: selectedUser.id,
      phone: selectedUser.phone,
      address: selectedUser.address
    },
    resolver: yupResolver(UpdateSchema)
  })

  useEffect(() => {
    reset({
      name: selectedUser.name,
      email: selectedUser.email,
      id: selectedUser.id,
      phone: selectedUser.phone,
      address: selectedUser.address
    })
  }, [selectedUser])

  // ** render user img
  const renderUserImg = () => {
    if (selectedUser !== null && selectedUser.avatar?.length) {
      return (
        <img  
          height='110'
          width='110'
          alt='user-avatar'
          src={selectedUser.avatar}
          className='img-fluid rounded mt-3 mb-2'
        />
      )
    } else {
      return (
        <Avatar
          initials
          color={selectedUser.avatarColor || 'light-primary'}
          className='rounded mt-3 mb-2'
          content={selectedUser.fullName}
          contentStyles={{
            borderRadius: 0,
            fontSize: 'calc(48px)',
            width: '100%',
            height: '100%'
          }}
          style={{
            height: '110px',
            width: '110px'
          }}
        />
      )
    }
  }

  const onSubmit = data => {
    if (Object.values(data).every(field => field.length > 0)) {
      setShow(false)
      dispatch(updateStaff(data))
    } else {
      for (const key in data) {
        if (data[key].length === 0) {
          setError(key, {
            type: 'manual'
          })
        }
      }
    }
  }

  const handleReset = () => {
    reset({
      // username: selectedUser.username,
      // lastName: selectedUser.fullName.split(' ')[1],
      // firstName: selectedUser.fullName.split(' ')[0]
      name: selectedUser.name,
      email: selectedUser.email,
      address: selectedUser.address,
      phone: selectedUser.phone
    })
  }

  const handleSuspendedClick = async () => {
    return MySwal.fire({
      title: 'Bạn có chắc muốn xóa tài khoản?',
      text: 'Việc xóa tài khoản này sẽ không thể hoàn tác lại.',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Xóa',
      customClass: {
        confirmButton: 'btn btn-primary',
        cancelButton: 'btn btn-outline-danger ms-1'
      },
      buttonsStyling: false
    }).then(function (result) {
      if (result.value) {
        dispatch(updateStaff({
          id: selectedUser.id,
          is_active: false
        }))
        MySwal.fire({
          icon: 'success',
          title: 'Thành công',
          text: 'Tài khoản đã bị xóa',
          customClass: {
            confirmButton: 'btn btn-success'
          }
        })
      } else if (result.dismiss === MySwal.DismissReason.cancel) {
        MySwal.fire({
          title: 'Hủy',
          text: 'Đã hủy :)',
          icon: 'error',
          customClass: {
            confirmButton: 'btn btn-success'
          }
        })
      }
    })
  }

  const handleActiveClick = async () => {
    return MySwal.fire({
      title: 'Bạn có chắc muốn mở khóa?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Mở khóa',
      customClass: {
        confirmButton: 'btn btn-primary',
        cancelButton: 'btn btn-outline-danger ms-1'
      },
      buttonsStyling: false
    }).then(function (result) {
      if (result.value) {
        dispatch(updateStaff({
          id: selectedUser.id,
          is_active: true
        }))
        MySwal.fire({
          icon: 'success',
          title: 'Thành công',
          text: 'Tài khoản đã được mở khóa',
          customClass: {
            confirmButton: 'btn btn-success'
          }
        })
      } else if (result.dismiss === MySwal.DismissReason.cancel) {
        MySwal.fire({
          title: 'Hủy',
          text: 'Đã hủy :)',
          icon: 'error',
          customClass: {
            confirmButton: 'btn btn-success'
          }
        })
      }
    })
  }

  return (
    <Fragment>
      <Card>
        <CardBody>
          <div className='user-avatar-section'>
            <div className='d-flex align-items-center flex-column'> 
              {renderUserImg()}
              <div className='d-flex flex-column align-items-center text-center'>
                <div className='user-info'>
                  <h4>{selectedUser.name !== null && selectedUser.name !== "" ? selectedUser.name : 'N/A'}</h4>
                  {selectedUser !== null ? (
                    <Badge color={roleColors[selectedUser.Role.name]} className='text-capitalize'>
                      {selectedUser.Role.name}
                    </Badge>
                  ) : null}
                </div>
              </div>
            </div>
          </div>
          <h4 className='fw-bolder border-bottom pb-50 mb-1'>Chi tiết</h4>
          <div className='info-container'>
            {selectedUser !== null ? (
              <ul className='list-unstyled'>
                <li className='mb-75'>
                  <span className='fw-bolder me-25'>Email:</span>
                  <span>{selectedUser.email}</span>
                </li>
                {/* <li className='mb-75'>
                  <span className='fw-bolder me-25'>Role:</span>
                  <span className='text-capitalize'>{selectedUser.Role.name}</span>
                </li> */}
                <li className='mb-75'>
                  <span className='fw-bolder me-25'>Địa chỉ:</span>
                  <span>{selectedUser.address && selectedUser.address !== '' ? selectedUser.address : "N/A"}</span>
                </li>
                <li className='mb-75'>
                  <span className='fw-bolder me-25'>SĐT:</span>
                  <span>{selectedUser.phone && selectedUser.phone !== '' ? selectedUser.phone : "N/A"}</span>
                </li>
              </ul>
            ) : null}
          </div>
          {userData.Role.id === 1 ? <div className='d-flex justify-content-center pt-2'>
            {selectedUser.is_active ? <Button color='primary' onClick={() => setShow(true)}>
              Sửa
            </Button> : null}
            {selectedUser.is_active ? <Button className='ms-1' color='danger' outline onClick={handleSuspendedClick}>
              Xóa
            </Button> : null}
            {/* <Button className='ms-1' color='success' outline onClick={handleActiveClick}>
              Mở khóa
            </Button> */}
          </div> : <div className='d-flex justify-content-center pt-2'>
            <Button color='primary' disabled>
              Sửa
            </Button>
            {selectedUser.is_active ? <Button className='ms-1' color='danger' outline disabled onClick={handleSuspendedClick}>
              Xóa
            </Button> : <Button className='ms-1' color='success' outline disabled onClick={handleActiveClick}>
              Mở khóa
            </Button>}
          </div>}
        </CardBody>
      </Card>

      <Modal 
        isOpen={show} 
        toggle={() => {
          setShow(!show)
          handleReset()
        }} 
        className='modal-dialog-centered modal-lg'
      >
        <ModalHeader 
          className='bg-transparent' 
          toggle={() => {
            handleReset()
            setShow(!show)
          }}
        ></ModalHeader>
        <ModalBody className='px-sm-5 pt-50 pb-5'>
          <div className='text-center mb-2'>
            <h1 className='mb-1'>Sửa thông tin</h1>
            {/* <p>Updating user details will receive a privacy audit.</p> */}
          </div>
          <Form onSubmit={handleSubmit(onSubmit)}>
            <Row className='gy-1 pt-75'>
              <Col md={6} xs={12}>
                <Label className='form-label' for='name'>
                  Tên
                </Label>
                <Controller
                  defaultValue={selectedUser?.name}
                  control={control}
                  id='name'
                  name='name'
                  render={({ field }) => (
                    <Input {...field} id='name' placeholder='John' invalid={errors.name && true} />
                  )}
                />
                {errors.name && (<FormFeedback>{errors.name.message}</FormFeedback>)}
              </Col>
              <Col md={6} xs={12}>
                <Label className='form-label' for='email'>
                  Email
                </Label>
                <Controller
                  defaultValue={selectedUser?.email}
                  control={control}
                  id='email'
                  name='email'
                  render={({ field }) => (
                    <Input {...field} id='email' placeholder='example@domain.com' invalid={errors.email && true} disabled/>
                  )}
                />
              </Col>
              <Col md={6} xs={12}>
                <Label className='form-label' for='phone'>
                  SĐT
                </Label>
                <Controller
                  defaultValue={selectedUser?.phone}
                  control={control}
                  id='phone'
                  name='phone'
                  render={({ field }) => (
                    <Input {...field} id='phone' invalid={errors.phone && true} type='number'/>
                  )}
                />
                {errors.phone && (<FormFeedback>{errors.phone.message}</FormFeedback>)}
              </Col>
              <Col md={6} xs={12}>
                <Label className='form-label' for='address'>
                  Địa chỉ
                </Label>
                <Controller
                  defaultValue={selectedUser?.address}
                  control={control}
                  id='address'
                  name='address'
                  render={({ field }) => (
                    <Input {...field} id='address' invalid={errors.address && true} />
                  )}
                />
                {errors.address && (<FormFeedback>{errors.address.message}</FormFeedback>)}
              </Col>
              <Col xs={12} className='text-center mt-2 pt-50'>
                <Button type='submit' className='me-1' color='primary' disabled={!isDirty}>
                  Lưu
                </Button>
                <Button
                  type='reset'
                  color='secondary'
                  outline
                  onClick={() => {
                    handleReset()
                    setShow(false)
                  }}
                >
                  Hủy
                </Button>
              </Col>
            </Row>
          </Form>
        </ModalBody>
      </Modal>
    </Fragment>
  )
}

export default UserInfoCard
