// ** React Imports
import { useEffect } from 'react'
import { useParams, Link, useNavigate } from 'react-router-dom'

// ** Store & Actions
import { getStaff } from '../store'
import { useSelector, useDispatch } from 'react-redux'

// ** Reactstrap Imports
import { Row, Col, Alert, Button } from 'reactstrap'

// ** User View Components
// import UserTabs from './Tabs'
// import PlanCard from './PlanCard'
import UserInfoCard from './UserInfoCard'

// ** Styles
import '@styles/react/apps/app-users.scss'

import { ArrowLeft } from 'react-feather'

const UserView = () => {
  // ** Store Vars
  const store = useSelector(state => state.staffs)
  const dispatch = useDispatch()

  // ** Hooks
  const { id } = useParams()

  // ** Get user on mount
  useEffect(() => {
    dispatch(getStaff(id))
  }, [dispatch])

  // const [active, setActive] = useState('1')

  // const toggleTab = tab => {
  //   if (active !== tab) {
  //     setActive(tab)
  //   }
  // }
  const navigate = useNavigate()
  useEffect(() => {
    console.log(store)
  }, [store])
  const handleBack = () => {
    navigate('/apps/staff/list')
  }

  return (store.selectedUser !== null && store.selectedUser !== undefined) ? (
    <div className='app-user-view'>
      <Button.Ripple className='btn-icon' color='flat-primary' onClick = {handleBack}>
        <ArrowLeft size={16} />
        <a> Quay lại</a>
      </Button.Ripple>
      <Row>
        <Col xl='4' lg='5' xs={{ order: 1 }} md={{ order: 0, size: 5 }}>
          <UserInfoCard selectedUser={store.selectedUser} />
          {/* <PlanCard /> */}
        </Col>
        <Col xl='8' lg='7' xs={{ order: 0 }} md={{ order: 1, size: 7 }}>
          {/* <UserTabs active={active} toggleTab={toggleTab} /> */}
        </Col>
      </Row>
    </div>
  ) : (
    <Alert color='danger'>
      <h4 className='alert-heading'>User not found</h4>
      <div className='alert-body'>
        User with id: {id} doesn't exist. Check list of all Users: <Link to='/apps/staff/list'>Users List</Link>
      </div>
    </Alert>
  )
}
export default UserView
